(async () => {
  const server = await createServer({
    server: { middlewareMode: true },
    appType: 'custom',
  });

  const React = await server.ssrLoadModule('react');
  const { renderToStaticMarkup } = await server.ssrLoadModule('react-dom/server');
  const { NotificationCard } = await server.ssrLoadModule('/src/components/ui/NotificationCard.tsx');
  const { TaskCard } = await server.ssrLoadModule('/src/components/home/TaskCard.tsx');
  const { MemoryRouter } = await server.ssrLoadModule('react-router-dom');
  const { QueryClient, QueryClientProvider } = await server.ssrLoadModule('@tanstack/react-query');

  const queryClient = new QueryClient();

  function renderTaskCard(card) {
    return renderToStaticMarkup(
      React.createElement(
        QueryClientProvider,
        { client: queryClient },
        React.createElement(
          MemoryRouter,
          null,
          React.createElement(TaskCard, {
            card: card,
            index: 0,
            onError: (err) => console.error(err)
          })
        )
      )
    );
  }

  function assert(cond, msg) {
    if (!cond) {
      console.error('ASSERTION FAILED:', msg);
      process.exit(1);
    }
  }

  // --- TEST 1: TaskCard with explicit verb & proactivity_tag ---
  const card1 = {
    id: 'c-1',
    type: 'email',
    urgency: 'critical',
    title: 'Urgent TLS cert rotation',
    summary: 'Certificate expires at 5 PM today.',
    status: 'new',
    proactivity_tag: 'Urgent Action',
    verb: 'Review',
    actions: [
      { id: 'a1', label: 'Approve Rotation', action_type: 'reply', verb: 'Review', payload: {} },
    ],
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const html1 = renderTaskCard(card1);
  assert(html1.includes('border-l-[3px] !border-l-[var(--urgency-critical)]'), 'Critical urgency rail missing in TaskCard');
  assert(html1.includes('Urgent Action'), 'Proactivity tag badge missing');
  assert(html1.includes('aria-label=\"Actionable observation pill\"'), 'Observation pill container missing');
  assert(html1.includes('>Review</button>'), 'Pinned Review verb button missing');
  assert(html1.includes('Certificate expires at 5 PM today.'), 'Summary text in pill missing');
  assert(html1.includes('⌝'), 'Trailing corner notch glyph missing');

  // --- TEST 2: TaskCard with verb=null, falling back to primary action verb ---
  const card2 = {
    id: 'c-2',
    type: 'calendar',
    urgency: 'high',
    title: 'Invite from Boardy',
    summary: 'Boardy invite for Thursday 5:30 PM',
    status: 'new',
    proactivity_tag: 'Decision Needed',
    verb: null,
    actions: [
      { id: 'a2', label: 'Accept invite', action_type: 'run', verb: 'Accept', payload: { config_id: 'default' } },
    ],
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const html2 = renderTaskCard(card2);
  assert(html2.includes('border-l-[3px] !border-l-[var(--urgency-high)]'), 'High urgency rail missing');
  assert(html2.includes('Decision Needed'), 'Proactivity tag missing');
  assert(html2.includes('>Accept</button>'), 'Fallback to primary.verb Accept failed');
  assert(html2.includes('Boardy invite for Thursday 5:30 PM'), 'Pill text missing');
  assert(html2.includes('⌝'), 'Corner notch missing');

  // --- TEST 3: TaskCard with verb=null, primary.verb=null, action_type=reply fallback ---
  const card3 = {
    id: 'c-3',
    type: 'email',
    urgency: 'medium',
    title: 'Question from Sarah',
    summary: 'Can you confirm the roadmap dates?',
    status: 'new',
    proactivity_tag: 'Autonomous Observation',
    verb: null,
    actions: [
      { id: 'a3', label: 'Reply to Sarah', action_type: 'reply', verb: null, payload: {} },
    ],
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const html3 = renderTaskCard(card3);
  assert(html3.includes('border-l-[3px] !border-l-[var(--urgency-medium)]'), 'Medium urgency rail missing');
  assert(html3.includes('>Reply</button>'), 'Fallback to action_type Reply failed');
  assert(html3.includes('⌝'), 'Corner notch missing');

  // --- TEST 4: TaskCard with NO actions and verb=null -> pill must NOT render ---
  const card4 = {
    id: 'c-4',
    type: 'alert',
    urgency: 'low',
    title: 'System update completed',
    summary: 'All packages upgraded smoothly.',
    status: 'done',
    proactivity_tag: null,
    verb: null,
    actions: [],
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const html4 = renderTaskCard(card4);
  assert(html4.includes('border-l-[3px] !border-l-[var(--urgency-low)]'), 'Low urgency rail missing');
  assert(!html4.includes('Actionable observation pill'), 'Observation pill rendered when verb was null!');
  assert(!html4.includes('⌝'), 'Corner notch rendered when verb was null!');

  console.log('ALL EMPIRICAL FRONTEND TESTS PASSED CLEANLY!');
  await server.close();
})();
"

